using System;
using System.Threading.Tasks;

public interface IRequest<TResponse> { }
public interface IRequestHandler<TRequest, TResponse> where TRequest : IRequest<TResponse>
{
    Task<TResponse> HandleAsync(TRequest request);
}

public record UpdateUserEmailCommand(int UserId, string NewEmail) : IRequest<bool>;

public class UpdateUserEmailHandler : IRequestHandler<UpdateUserEmailCommand, bool>
{
    public Task<bool> HandleAsync(UpdateUserEmailCommand request)
    {
        if (!request.NewEmail.Contains("@"))
        {
            throw new ArgumentException("Format email tidak valid!");
        }

        Console.WriteLine($"[Command] Validasi sukses. Mengupdate email user {request.UserId} menjadi {request.NewEmail}");
        return Task.FromResult(true);
    }
}

public record GetUserQuery(int UserId) : IRequest<string>;

public class GetUserHandler : IRequestHandler<GetUserQuery, string>
{
    public Task<string> HandleAsync(GetUserQuery request)
    {
        Console.WriteLine($"[Query] Mengambil data read-only untuk user {request.UserId}");
        return Task.FromResult($"User {request.UserId} (user_{request.UserId}@corp.com)");
    }
}

public class Program
{
    public static async Task Main()
    {
        var commandHandler = new UpdateUserEmailHandler();
        var queryHandler = new GetUserHandler();

        var cmd = new UpdateUserEmailCommand(101, "new_ceo@enterprise.com");
        await commandHandler.HandleAsync(cmd);

        var query = new GetUserQuery(101);
        var result = await queryHandler.HandleAsync(query);
        Console.WriteLine($"[Query] Hasil: {result}");
    }
}
